use serde::{Deserialize, Serialize};

pub const MAX_POINTS: usize = 4096;
pub const MAX_TEXT: usize = 4096;
pub const MAX_OBJECT_ID: usize = 64;
pub const ZOOM_RANGE: std::ops::RangeInclusive<i32> = -40..=40;
pub const MAX_COLOUR: u8 = 5;
pub const MAX_RGB: u32 = 0xFF_FFFF;
pub const WIDTH_RANGE: std::ops::RangeInclusive<f64> = 0.5..=96.0;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Bbox {
    #[serde(rename = "minX")]
    pub min_x: f64,
    #[serde(rename = "minY")]
    pub min_y: f64,
    #[serde(rename = "maxX")]
    pub max_x: f64,
    #[serde(rename = "maxY")]
    pub max_y: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum PencilSize {
    Small,
    Medium,
    Large,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum StrokeStyle {
    #[default]
    Pen,
    Highlighter,
    Dashed,
    Uniform,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ShapeKind {
    Rectangle,
    Ellipse,
    Line,
    Arrow,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ShapeFill {
    None,
    Tint,
}

pub type Point = (f64, f64, f64);

pub type ShapePoint = (f64, f64);

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Stroke {
    pub object_id: String,
    pub native_zoom: i32,
    pub bbox: Bbox,
    pub colour: u8,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rgb: Option<u32>,
    pub size: PencilSize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f64>,
    #[serde(default)]
    pub style: StrokeStyle,
    pub points: Vec<Point>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Shape {
    pub object_id: String,
    pub native_zoom: i32,
    pub bbox: Bbox,
    pub colour: u8,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rgb: Option<u32>,
    pub size: PencilSize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f64>,
    #[serde(default)]
    pub style: StrokeStyle,
    pub kind: ShapeKind,
    pub start: ShapePoint,
    pub end: ShapePoint,
    pub fill: ShapeFill,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Text {
    pub object_id: String,
    pub native_zoom: i32,
    pub bbox: Bbox,
    pub colour: u8,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rgb: Option<u32>,
    pub size: PencilSize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f64>,
    pub text: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type")]
pub enum StallionObject {
    Stroke(Stroke),
    Shape(Shape),
    Text(Text),
}

struct Common<'a> {
    object_id: &'a str,
    native_zoom: i32,
    bbox: &'a Bbox,
    colour: u8,
    rgb: Option<u32>,
    width: Option<f64>,
}

impl StallionObject {
    pub fn object_id(&self) -> &str {
        self.common().object_id
    }

    pub fn bbox(&self) -> &Bbox {
        self.common().bbox
    }

    fn common(&self) -> Common<'_> {
        match self {
            StallionObject::Stroke(o) => Common {
                object_id: &o.object_id,
                native_zoom: o.native_zoom,
                bbox: &o.bbox,
                colour: o.colour,
                rgb: o.rgb,
                width: o.width,
            },
            StallionObject::Shape(o) => Common {
                object_id: &o.object_id,
                native_zoom: o.native_zoom,
                bbox: &o.bbox,
                colour: o.colour,
                rgb: o.rgb,
                width: o.width,
            },
            StallionObject::Text(o) => Common {
                object_id: &o.object_id,
                native_zoom: o.native_zoom,
                bbox: &o.bbox,
                colour: o.colour,
                rgb: o.rgb,
                width: o.width,
            },
        }
    }

