646	      return;
647	    const wait = publishedAt + PRESENCE_THROTTLE_MS - performance.now();
648	    if (wait > 0) {
649	      if (publishTimer === undefined) {
650	        publishTimer = setTimeout(() => {
651	          publishTimer = undefined;
652	          publishViewport();
653	        }, wait);
654	      }
655	      return;
656	    }
657	    published = viewport;
658	    publishedAt = performance.now();
659	    awareness.setLocalStateField("presence", {
660	      colour: presenceColour(awareness.clientID),
661	      viewport,
662	    });
663	  };
664	
665	  const shareCursor = (screen: Point | undefined) => {
666	    if (!awareness) return;
667	    if (!screen) {
668	      awareness.setLocalStateField("cursor", null);
669	      return;
670	    }
671	    const now = performance.now();
672	    if (now - cursorSentAt < CURSOR_THROTTLE_MS) return;
673	    cursorSentAt = now;
674	    awareness.setLocalStateField("cursor", screenToWorld(camera, screen));
675	  };
676	
677	  const reportView = () => {
678	    const contentLevels = [...new Set(ordered.map((entry) => entry.object.nativeZoom))].sort(
679	      (a, b) => a - b,
680	    );
681	    const level = levelOf(camera.zoom);
682	    if (
683	      reported &&
684	      reported.level === level &&
685	      reported.contentLevels.join() === contentLevels.join()
686	    )
687	      return;
688	    reported = { level, contentLevels };
689	    onView(reported);
690	  };
691	
692	  const updateView = () => {
693	    const { width, height } = size();
694	    source.view(viewBounds(camera, width, height), camera.zoom);
695	  };
696	
697	  const settle = () => {
698	    clearTimeout(settleTimer);
699	    settleTimer = setTimeout(() => saveCamera(boardId, camera), 150);
700	    updateView();
701	  };
702	
703	  const moveCamera = (next: Camera) => {
704	    if (!isCamera(next)) return;
705	    camera = next;
706	    requestRender();
707	    settle();
708	    reportView();
709	    publishViewport();
710	  };
711	
712	  const shareDraft = (next: Draft) => {
713	    const { objectId, rgb, width, style, nativeZoom, points } = next;
714	    publisher?.start({
715	      strokeId: objectId,
716	      colour: nearestColour(rgb),
717	      rgb,
718	      size: nearestSize(width),
719	      width,
720	      style,
721	      nativeZoom,
722	    });
723	    publisher?.extend(points);
724	  };
725	  const follow = createFollow({
726	    camera: () => camera,
727	    size,
728	    move: moveCamera,
729	    requestFrame: (step) => requestAnimationFrame(step),
730	    cancelFrame: (handle) => cancelAnimationFrame(handle),
731	    now: () => performance.now(),
732	    onChange: reportPresence,
733	  });
734	
735	  const commit = () => {
736	    if (!draft) return;
737	    publisher?.finish();
738	    const stored = finishDraft(draft);
739	    draft = undefined;
740	    if (stored) {
741	      source.commit(stored);
742	      onCommit();
743	    }
744	    publisher?.clear();
745	  };
746	
747	  const commitShape = () => {
748	    if (!shapeDraft) return;
749	    const stored = finishShape(shapeDraft);
750	    shapeDraft = undefined;
751	    if (!stored) return;
752	    source.commit(stored);
753	    onCommit();
754	  };
755	
756	  const toLocal = (clientX: number, clientY: number): Point => {
757	    const rect = canvas.getBoundingClientRect();
758	    return { x: clientX - rect.left, y: clientY - rect.top };
759	  };
760	
761	  const localPoint = (event: PointerEvent | WheelEvent): Point =>
762	    toLocal(event.clientX, event.clientY);
763	
764	  const pressureOf = (event: PointerEvent): number =>
765	    event.pointerType === "pen" ? Math.min(1, Math.max(0, event.pressure)) : 0.5;
766	
767	  const addPoint = (screen: Point, pressure: number) => {
768	    if (!draft) return;
769	    const world = screenToWorld(camera, screen);
770	    if (draft.points.length >= MAX_POINTS) {
771	      const next = continueDraft(draft);
772	      commit();
773	      draft = next;
774	      shareDraft(next);
775	    }
776	    const point: [number, number, number] = [world.x, world.y, pressure];
777	    draft.points.push(point);
778	    publisher?.extend([point]);
779	  };
780	
781	  const pointerKind = (event: PointerEvent): PointerKind =>
782	    event.pointerType === "pen" || event.pointerType === "touch" ? event.pointerType : "mouse";
783	
784	  const apply = (effects: readonly Effect[], event?: PointerEvent) => {
785	    for (const effect of effects) {
786	      switch (effect.type) {
787	        case "StartStroke": {
788	          const tool = currentTool();
789	          if (tool.mode === "Select") {
790	            startDrag(effect.point);
791	            break;
792	          }
793	          if (tool.mode === "Eraser") {
794	            eraser = undefined;
795	            eraseTo(effect.point);
796	            break;
797	          }
798	          if (tool.mode === "Shape") {
799	            shapeDraft = startShape(
800	              tool.shape,
801	              tool.fill,
802	              effect.secondary ? tool.secondary : tool.primary,
803	              tool.width,
804	              tool.style,
805	              camera.zoom,
806	              screenToWorld(camera, effect.point),
807	            );
808	            break;
809	          }
810	          draft = startDraft(
811	            effect.secondary ? tool.secondary : tool.primary,
812	            tool.width,
813	            tool.style,
814	            camera.zoom,
815	          );
816	          shareDraft(draft);
817	          addPoint(effect.point, event ? pressureOf(event) : 0.5);
818	          break;
819	        }
820	        case "StartResize":
821	          startResize(effect.point);
822	          break;
823	        case "ExtendStroke": {
824	          if (!event) break;
825	          if (resizing) {
826	            resizeTo(localPoint(event));
827	            break;
828	          }
829	          const samples = event.getCoalescedEvents?.() ?? [];
830	          for (const sample of samples.length > 0 ? samples : [event]) {
831	            if (drag) dragTo(localPoint(sample));
832	            else if (eraser) eraseTo(localPoint(sample));
833	            else if (shapeDraft) shapeDraft.end = screenToWorld(camera, localPoint(sample));
834	            else addPoint(localPoint(sample), pressureOf(sample));
835	          }
836	          break;
837	        }
838	        case "CommitStroke":
839	          eraser = undefined;
840	          drop();
841	          finishResize();
842	          commit();
843	          commitShape();
844	          source.history.checkpoint();
845	          break;
846	        case "DiscardStroke":
847	          eraser = undefined;
848	          drag = undefined;
849	          resizing = undefined;
850	          draft = undefined;
851	          shapeDraft = undefined;
852	          publisher?.clear();
853	          source.history.checkpoint();
854	          break;
855	        case "Pan":
856	          follow.stop();
857	          moveCamera(pan(camera, effect.dx, effect.dy));
858	          break;
859	        case "Pinch":
860	          follow.stop();
861	          moveCamera(pinch(camera, effect));
862	          break;
863	      }
864	    }
865	    if (effects.length > 0) requestRender();
866	  };
867	
868	  const stopAnimation = () => {
869	    cancelAnimationFrame(animation);
870	    animation = 0;
871	  };
872	
873	  const zoomToLevel = (level: number) => {
874	    follow.stop();
875	    stopAnimation();
876	    const from = camera;
877	    const { width, height } = size();
878	    const centre = { x: width / 2, y: height / 2 };
879	    const target = zoomForLevel(level);
880	    const started = performance.now();
881	    const step = (now: number) => {
882	      const t = Math.min(1, (now - started) / LEVEL_ANIMATION_MS);
883	      moveCamera(zoomTo(from, centre, from.zoom * (target / from.zoom) ** easeOut(t)));
884	      if (t < 1) {
885	        animation = requestAnimationFrame(step);
886	        return;
887	      }
888	      animation = 0;
889	      moveCamera(zoomTo(from, centre, target));
890	    };
891	    animation = requestAnimationFrame(step);
892	  };
893	
894	  const isPointerEvent = (event: Event): event is PointerEvent => "pointerId" in event;
895	
896	  const onDrag = ({ event, intentional }: { event: Event; intentional: boolean }) => {
897	    if (!isPointerEvent(event)) return;
898	    const first = event.type === "pointerdown";
899	    const cancelled = event.type === "pointercancel";
900	    const last = cancelled || event.type === "pointerup" || event.type === "lostpointercapture";
901	    if (first) {
902	      event.preventDefault();
903	      stopAnimation();
904	      dragButton = event.button;
905	    }
906	    const effects = input.drag(
907	      {
908	        first,
909	        last,
910	        cancelled,
911	        intentional,
912	        kind: pointerKind(event),
913	        button: dragButton,
914	        point: localPoint(event),
915	        time: event.timeStamp,
916	      },
917	      {
918	        panTool: currentTool().mode === "Pan",
919	        spaceDown,
920	        onHandle:
921	          first && currentTool().mode === "Select" && handleAt(localPoint(event)) !== undefined,
922	      },
923	    );
924	    apply(effects, event);
925	    if (!first || event.pointerType !== "touch") return;
926	    clearTimeout(pendingTimer);
927	    pendingTimer = setTimeout(() => apply(input.tick(performance.now())), PENDING_MS);
928	  };
929	
930	  const onPinch = ({
931	    first,
932	    last,
933	    origin,
934	    da,
935	  }: {
936	    first: boolean;
937	    last: boolean;
938	    origin: [number, number];
939	    da: [number, number];
940	  }) => {
941	    if (first) {
942	      stopAnimation();
943	      follow.stop();
944	    }
945	    apply(input.pinch({ first, last, origin: toLocal(origin[0], origin[1]), distance: da[0] }));
946	  };
947	
948	  const onWheel = ({ event }: { event: WheelEvent }) => {
949	    event.preventDefault();
950	    stopAnimation();
951	    follow.stop();
952	    const factor = wheelFactor(event.ctrlKey ? event.deltaY * 3 : event.deltaY, event.deltaMode);
953	    moveCamera(zoomAt(camera, localPoint(event), factor));
954	  };
955	
956	  const onPointerMove = (event: PointerEvent) => shareCursor(localPoint(event));
957	
958	  const onKey = (event: KeyboardEvent) => {
959	    if (event.target instanceof HTMLInputElement) return;
960	    if (event.type === "keydown" && (event.key === "Delete" || event.key === "Backspace")) {
961	      if (selected === undefined || currentTool().mode !== "Select") return;
962	      event.preventDefault();
963	      source.erase(selected);
964	      source.history.checkpoint();
965	      selected = undefined;
966	      requestRender();
967	      return;
968	    }
969	    if (event.code !== "Space") return;
970	    event.preventDefault();
971	    spaceDown = event.type === "keydown";
972	  };
973	
974	  const onPointerLeave = () => shareCursor(undefined);
975	
976	  const preventDefault = (event: Event) => event.preventDefault();
977	
978	  const unobserve = source.objects.observe(onObjects);
979	  const unobserveHints = source.hints.observe(requestRender);
980	  awareness?.on("change", onAwareness);
981	
982	  const observer = new ResizeObserver(() => {
983	    resize();
984	    settle();
985	  });
986	  observer.observe(canvas);
987	
988	  const gesture = new Gesture(
989	    canvas,
990	    { onDrag, onPinch, onWheel },
991	    {
992	      eventOptions: { passive: false },
993	      drag: {
994	        threshold: DRAG_THRESHOLD_PX,
995	        triggerAllEvents: true,
996	        pointer: { buttons: -1, keys: false },
997	      },
998	      pinch: { pointer: { touch: true }, pinchOnWheel: false },
999	    },
1000	  );
1001	  canvas.addEventListener("pointermove", onPointerMove);
1002	  canvas.addEventListener("pointerleave", onPointerLeave);
1003	  canvas.addEventListener("contextmenu", preventDefault);
1004	  for (const type of BLOCKED_TOUCH_EVENTS) {
1005	    canvas.addEventListener(type, preventDefault, { passive: false });
1006	  }
1007	  window.addEventListener("keydown", onKey);
1008	  window.addEventListener("keyup", onKey);
1009	
1010	  resize();
1011	  onObjects(new Set(source.objects.keys()));
1012	  onAwareness();
1013	  updateView();
1014	  reportView();
1015	
1016	  return {
1017	    zoomToLevel,
1018	    follow(clientId) {
1019	      if (clientId === undefined || clientId === follow.target) {
1020	        follow.stop();
1021	        return;
1022	      }
1023	      stopAnimation();
1024	      follow.start(clientId);
1025	    },
1026	    dispose() {
1027	      clearTimeout(settleTimer);
1028	      clearTimeout(publishTimer);
1029	      follow.dispose();
1030	      clearTimeout(pendingTimer);
1031	      publisher?.clear();
1032	      cancelAnimationFrame(frame);
1033	      stopAnimation();
1034	      gesture.destroy();
1035	      observer.disconnect();
1036	      canvas.removeEventListener("pointermove", onPointerMove);
1037	      canvas.removeEventListener("pointerleave", onPointerLeave);
1038	      canvas.removeEventListener("contextmenu", preventDefault);
1039	      for (const type of BLOCKED_TOUCH_EVENTS) canvas.removeEventListener(type, preventDefault);
1040	      window.removeEventListener("keydown", onKey);
1041	      window.removeEventListener("keyup", onKey);
1042	      unobserve();
