      await palette.getByRole("button", { name: `${stroke.width} px pencil` }).tap();
      await drawWithTouch(page, stroke.points);
      await page.waitForTimeout(500);
    }
    await page.waitForTimeout(800);
    const drawn = await ratios(strokes, "drawn");
